                  h.source, null, h.snapshots, h.publisher, h.inspector, h.clock));
      assertThrows(
          NullPointerException.class,
          () ->
              ScenarioApplicationAssembly.create(
                  h.source, h.keys, null, h.publisher, h.inspector, h.clock));
      assertThrows(
          NullPointerException.class,
