  private static InboxCompletion saved(
      InboxResponseInspectorTest.Fixture f,
      String layout,
      String code,
      InboxResultReference ref,
      Map<String, String> values,
      int count)
      throws Exception {
    byte[] wire = wire(layout, code, values, count);
