      assertEquals(1, initial);
      assertEquals(99, replay);
    }
    assertEquals(1, passwordChecks.get());
    assertEffects(1, 1, 1);
    try (Connection c = database.transaction()) {
      assertInbox(c, "COMPLETED", "AUTH_SESSION", "利用者", PASSWORD, "127.0.0.1");
